const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define the Mississippi River Delta Basin (Plaquemines-Balize Delta)
  const deltaPoint = ee.Geometry.Point([-89.3, 29.3]);
  const deltaRegion = deltaPoint.buffer(50000); // 50km radius

  // 2. Date range
  const startDate = '2025-01-21';
  const endDate = '2025-01-25';

  // 3. Try MODIS Snow Cover first (most reliable for snow detection)
  let snowCollection = ee.ImageCollection('MODIS/006/MOD10A1')
    .filterDate(startDate, endDate)
    .filterBounds(deltaRegion);

  const collectionSize = await snowCollection.size().getInfo();
  console.log(`MODIS Snow images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No MODIS snow data available for this period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Get the snow cover data
  const snowComposite = snowCollection.max();

  // 5. Calculate snow statistics
  const stats = await snowComposite.select('NDSI_Snow_Cover').reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.mean(),
      sharedInputs: true
    }).combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: deltaRegion,
    scale: 500,
    maxPixels: 1e9
  }).getInfo();

  const maxSnow = stats['NDSI_Snow_Cover_max'];
  const meanSnow = stats['NDSI_Snow_Cover_mean'];
  const pixelCount = stats['NDSI_Snow_Cover_count'];

  console.log(`Valid pixels: ${pixelCount}`);
  console.log(`Max snow cover value: ${maxSnow}`);
  console.log(`Mean snow cover value: ${meanSnow !== null ? meanSnow.toFixed(2) : 'null'}`);

  // 6. Validation
  if (pixelCount === 0 || pixelCount === null) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (maxSnow === null || maxSnow === undefined) {
    console.log('Calculation failed - invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Snow detection logic
  // MODIS NDSI_Snow_Cover: 0-100 = snow cover %, 200 = missing data, 201 = no decision, 
  // 211 = night, 237 = inland water, 239 = ocean, 250 = cloud, 254 = detector saturated, 255 = fill
  // Values 10-100 indicate snow presence (>10% snow cover)

  if (maxSnow >= 10 && maxSnow <= 100) {
    console.log(`Snow detected! Max snow cover: ${maxSnow}%`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`No snow detected. Max value: ${maxSnow} (likely water/cloud/no-snow)`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
